using System;
using System.Linq;
using System.Drawing;
using System.Windows.Forms;
using System.Collections.Generic;
namespace JingFamily {
 public class RelationWindow:Form {
  ComboBox from,to;TextBox output;
  public static string FindPath(string start,string end){if(start==end)return "选择的是同一位成员："+Store.Name(start);var queue=new Queue<string>();var previous=new Dictionary<string,Tuple<string,string>>();queue.Enqueue(start);previous[start]=null;while(queue.Count>0){string id=queue.Dequeue();var p=Store.Get(id);if(p==null)continue;var edges=new List<Tuple<string,string>>();if(p.FatherId!="")edges.Add(Tuple.Create(p.FatherId,"父亲"));if(p.MotherId!="")edges.Add(Tuple.Create(p.MotherId,"母亲"));foreach(var spouse in p.Spouses)edges.Add(Tuple.Create(spouse,"配偶"));foreach(var c in Store.Data.People.Where(x=>x.FatherId==id||x.MotherId==id))edges.Add(Tuple.Create(c.Id,c.Gender=="男"?"儿子":c.Gender=="女"?"女儿":"子女"));foreach(var edge in edges){if(previous.ContainsKey(edge.Item1))continue;previous[edge.Item1]=Tuple.Create(id,edge.Item2);if(edge.Item1==end){var path=new List<string>();string cur=end;while(cur!=start){var step=previous[cur];path.Add("  ↓ "+step.Item2+"\r\n"+Store.Name(cur));cur=step.Item1;}path.Reverse();return Store.Name(start)+"\r\n"+String.Join("\r\n",path);}queue.Enqueue(edge.Item1);}}return "当前家谱中未找到连接两人的亲缘路径。请先补全父母或配偶关系。";}
  public RelationWindow(){Ui.ApplyBrand(this);Text="亲缘路径查询";Size=new Size(660,570);MinimumSize=new Size(600,450);Font=Ui.Font();BackColor=Ui.Cream;StartPosition=FormStartPosition.CenterParent;var top=new FlowLayoutPanel{Dock=DockStyle.Top,Height=105,AutoSize=true,Padding=new Padding(20),WrapContents=true};from=new ComboBox{Width=220,DropDownStyle=ComboBoxStyle.DropDownList};to=new ComboBox{Width=220,DropDownStyle=ComboBoxStyle.DropDownList};foreach(var p in Store.Data.People.OrderBy(p=>p.Name)){string label=p.Name+" · "+p.Birth+" ["+p.Id.Substring(0,Math.Min(6,p.Id.Length))+"]";from.Items.Add(new PickItem(p.Id,label));to.Items.Add(new PickItem(p.Id,label));}if(from.Items.Count>0){from.SelectedIndex=0;to.SelectedIndex=Math.Min(1,to.Items.Count-1);}top.Controls.Add(new InputFrame(from){Width=228,Height=42,Margin=new Padding(0,0,10,10)});top.Controls.Add(new InputFrame(to){Width=228,Height=42,Margin=new Padding(0,0,10,10)});top.Controls.Add(Ui.Button("查询路径",()=>{if(from.SelectedItem==null||to.SelectedItem==null){Ui.Info("请先添加成员。");return;}output.Text=FindPath(((PickItem)from.SelectedItem).Id,((PickItem)to.SelectedItem).Id);},true));Controls.Add(top);var body=new Panel{Dock=DockStyle.Fill,Padding=new Padding(20,0,20,20)};output=new TextBox{Dock=DockStyle.Fill,Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Vertical,BackColor=Color.White,Font=Ui.Font(12),Text="选择两位成员，查询由父母、子女与配偶关系连接的最短路径。\r\n\r\n结果展示关系链，便于了解旁系亲属之间的联系。"};body.Controls.Add(output);Controls.Add(body);body.BringToFront();}
 }
}
